<script>const body=document.getElementById('lines'),template=document.getElementById('line-template');let index=0;function totals(){let d=0,c=0;body.querySelectorAll('tr').forEach(row=>{d+=Number(row.querySelector('[data-name="debit"]').value||0);c+=Number(row.querySelector('[data-name="credit"]').value||0)});document.getElementById('total-debit').textContent=d.toFixed(2);document.getElementById('total-credit').textContent=c.toFixed(2)}function add(){const row=template.content.firstElementChild.cloneNode(true);row.querySelectorAll('[data-name]').forEach(input=>input.name=`lines[${index}][${input.dataset.name}]`);index++;row.querySelector('.remove-line').onclick=()=>{if(body.children.length>2)row.remove();totals()};row.querySelectorAll('.amount').forEach(input=>input.oninput=totals);body.append(row)}document.getElementById('add-line').onclick=add;add();add();</script>@endsection
